    } else {
        0.0
    };
    score -= 7.2 * closure_value * (0.35 + 0.65 * progress);

    let residual_floor = (item * 2.0).max(1.0);
    if residual > 0.0 && residual < residual_floor && post_ratio < 0.24 {
        let narrow_slack = 1.0 - residual / residual_floor;
        score += 6.4 * narrow_slack * (0.48 + 0.52 * remaining);
    }

    let dead_ratio = (1.0 - utilization).max(0.0);
    let dead_band = (dead_ratio - 0.72).max(0.0) / 0.28;
    score += 11.0 * dead_band.min(1.0) * (0.35 + 0.65 * progress);

    if !is_new && post_residual > 0 && post_residual < item {
        let stranded_ratio = (item - post_residual) as f64 / item.max(1.0);
        score += 7.0 * stranded_ratio * stranded_ratio * (0.45 + 0.55 * remaining);
    }

    if next > 0.0 && residual > 0.0 && residual < next {
        let next_gap = (next - residual) / next;
        let near_gap = (1.0 - next_gap).max(0.0);
        score += 8.0 * next_gap * near_gap * (0.30 + 0.70 * progress);
    }

    let effective_waste = if post_residual == 0 {
        0.0
    } else {
        let usable = (post_residual / item.max(1.0)).floor() * item;
        (post_residual as f64 - usable) / capacity
    };
    score += 16.0 * effective_waste * (0.50 + 0.50 * remaining);

    let dead_space_ratio = post_ratio;
    let critical_dead_space = if dead_space_ratio > 0.72 {
        (dead_space_ratio - 0.72) / 0.28
    } else {
        0.0
    };
    score += 8.5 * critical_dead_space.min(1.0) * (0.50 + 0.50 * progress);

    let residue = (post_residual % item.max(1.0)) as f64;
    let residue_ratio = residue / item.max(1.0);
    score += 10.0 * residue_ratio * (0.35 + 0.65 * remaining);

    let future_value = if next > 0.0 && residual >= next {
        (residual - next) / capacity
    } else {
        0.0
    };
    score += 7.0 * future_value * (0.30 + 0.70 * progress);

    let scarcity_discount = if fitting_bins_count == 1 {
        remaining * 0.5
    } else {
        0.0
    };
    score -= scarcity_discount * post_ratio;

    if !is_new && post_ratio > 0.84 && item_fraction > 0.08 {
        let compactness = (post_ratio - 0.84) / 0.16;
        score -= 5.0 * compactness.min(1.0) * remaining;
    }

    let live_fragments = if post_residual == 0 || item <= 0.0 {
