    let item_ratio = (item / capacity).clamp(0.0, 1.0);
    let mean_ratio = (mean_residual / capacity).clamp(0.0, 1.0);

    let mut score = residual;

    if is_new {
        score -= 42.0 + 7.0 * progress;
    }

    let utilization = 1.0 - post_ratio;
    score -= 53.0 * utilization;

    let fit_quality = (residual / item.max(1.0)).min(1.0);
    score -= 12.0 * fit_quality;

    if post_residual == 0 {
        score -= 28.0 + 9.0 * remaining;
    } else if post_residual < item_size {
        score += 15.0 * (1.0 - residual / item.max(1.0));
    }

    if next > 0.0 {
        if residual >= next {
            score -= 21.0;
            let coverage = (residual / next).min(4.0);
            score -= 7.0 * (coverage - 1.0);
        } else {
            score += 17.0;
            let deficit = next - residual;
            score += 27.0 * (deficit / next).min(1.0);
        }

        let remainder = (post_residual % next.max(1.0)) as f64 / next;
        score += 12.0 * remainder;

        if post_residual >= next.max(1.0) {
            score -= 5.0 * (1.0 - progress);
        }
    }

    let scarcity = if fitting_bins_count == 0 {
        37.0
    } else if fitting_bins_count == 1 {
        11.0 + 8.0 * remaining
    } else {
        0.0
    };
    score += scarcity;

    score += 0.020 * (residual - mean_residual).abs();

    score += 4.5 * progress * post_ratio;
    score += 0.014 * open_bins_count as f64 * post_ratio;

    score += 0.050 * residual * remaining * remaining;

    let dead_space = if post_residual == 0 {
        0.0
    } else if residual < item {
        13.0 * (1.0 - residual / item.max(1.0))
    } else {
        4.5 * post_ratio
    };
    score += dead_space;

    score += 8.0 * post_ratio.powf(1.42) * (0.30 + 0.70 * progress);

    if fitting_bins_count > 1 {
        let congestion = (fitting_bins_count as f64).ln() / 3.0;
        score += 2.8 * congestion * post_ratio;
    }

    let next_headroom = if next > 0.0 {
        (residual / next).min(1.0)
    } else {
        0.0
    };
    score -= 7.0 * next_headroom * remaining;

    let marginal_waste = (post_ratio - mean_ratio).max(0.0);
    score += 16.0 * marginal_waste * (0.50 + 0.50 * progress);

    let stranded = post_ratio * (1.0 - item_ratio).max(0.0);
    score += 12.0 * stranded;

    if post_residual > 0 && next > 0.0 {
        let next_slack = (post_residual % next.max(1.0)) as f64;
        let slice_efficiency = (1.0 - next_slack / post_residual as f64).clamp(0.0, 1.0);
        score -= 9.0 * slice_efficiency * (0.40 + 0.60 * remaining);
    }

    if fitting_bins_count > 1 && post_residual < next {
        score += 6.0 * (next - post_residual as f64) / next.max(1.0);
    }

    score += 0.070 * (residual - mean_residual).max(0.0) * (0.35 + 0.65 * progress);

    let fill_gain = (capacity - residual).max(0.0);
    score -= 0.095 * fill_gain * (0.55 + 0.45 * progress);

    let fragment_band = if post_ratio < 0.10 {
        1.0
    } else if post_ratio < 0.20 {
        (0.20 - post_ratio) / 0.10
    } else {
        0.0
    };
    score += 17.0 * fragment_band * (0.40 + 0.60 * remaining);

    if next > 0.0 && residual >= next {
        let next_after = (residual - next).max(0.0);
        score += 4.0 * next_after / next.min(capacity);
    }

    let residual_band = if post_ratio <= 0.05 {
        1.0
    } else if post_ratio <= 0.16 {
        (0.16 - post_ratio) / 0.11
    } else {
        0.0
    };
    score += 11.0 * residual_band * (0.35 + 0.65 * progress);

    if fitting_bins_count > 1 {
        let competition = (fitting_bins_count as f64 - 1.0).min(5.0) / 5.0;
        score += 7.0 * competition * post_ratio * (0.45 + 0.55 * progress);
    }

    if post_residual > 0 && next > 0.0 {
        let next_fit = if post_residual >= next {
            1.0
        } else {
            1.0 - (next - post_residual as f64) / next
        };
        score -= 7.0 * next_fit * remaining;
    }

    if !is_new && pre_ratio > post_ratio {
        score -= 24.0 * (pre_ratio - post_ratio) * (0.55 + 0.45 * progress);
    }

    score += 2.4 * (post_ratio - mean_ratio).abs() * (0.20 + 0.80 * progress);

    let reachable_gap = (post_ratio - mean_ratio).abs();
    let gap_bonus = if reachable_gap < 0.030 {
        (0.030 - reachable_gap) / 0.030
    } else {
        0.0
    };
    score -= 6.5 * gap_bonus * remaining;

    let ratio_penalty = if post_ratio < 0.08 {
        (0.08 - post_ratio) / 0.08
    } else if post_ratio > 0.25 {
        ((post_ratio - 0.25) / 0.25).min(1.0)
    } else {
        0.0
    };
    score += 10.0 * ratio_penalty * (0.35 + 0.65 * remaining);

    if !is_new && fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - post_ratio) * remaining;
    }

    let exact_need = if next > 0.0 {
        let slack = (post_residual % next.max(1.0)) as f64;
        (next - slack).max(0.0) / next
    } else {
        0.0
    };
    score -= 8.0 * exact_need * (0.25 + 0.75 * remaining);

    let two_step_fit = if next > 0.0 {
        let after_next = residual - next;
        if after_next >= next {
            1.0
        } else {
            (after_next / next).max(0.0)
        }
    } else {
        0.0
    };
    score -= 5.0 * two_step_fit * (0.20 + 0.80 * remaining);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
