    let residual_pressure = post_ratio.powf(1.48);
    score += 7.1 * residual_pressure * (0.28 + 0.72 * progress);

    if fitting_bins_count > 1 {
        let congestion = (fitting_bins_count as f64).ln() / 3.0;
