    if post_residual > 0 && next > 0.0 {
        let next_slack = (post_residual % next.max(1.0)) as f64;
        let slice_efficiency = (1.0 - next_slack / post_residual as f64).clamp(0.0, 1.0);
        score -= 7.5 * slice_efficiency * (0.38 + 0.62 * remaining);
