    let fill_gain = (capacity - residual).max(0.0);
    score -= 0.084 * fill_gain * (0.52 + 0.48 * progress);

    if !is_new && post_ratio < 0.16 && post_residual > 0 {
        let tiny_fragment = 1.0 - post_ratio / 0.16;
        score += 13.5 * tiny_fragment * (0.42 + 0.58 * remaining);
    }

    if next > 0.0 && residual >= next {
        let next_after = (residual - next).max(0.0);
        let next_ratio = next_after / next.min(capacity);
