    let residue = (post_residual % item.max(1.0)) as f64;
    let residue_ratio = residue / item.max(1.0);
    score += 10.0 * residue_ratio * (0.35 + 0.65 * remaining);

    let future_value = if next > 0.0 && residual >= next {
