    };
    score += 7.0 * future_value * (0.30 + 0.70 * progress);

    if fitting_bins_count == 1 {
        score -= remaining * 0.5 * post_ratio;
    }

    if !is_new && post_ratio > 0.84 && item_fraction > 0.08 {
        let compactness = ((post_ratio - 0.84) / 0.16).min(1.0);
        score -= 5.0 * compactness * remaining;
    }

    let live_fragments = if post_residual == 0 || item <= 0.0 {
        0.0
    } else {
        let count = (post_residual as f64 / item).floor();
        let loss = post_residual as f64 - count * item;
        loss / capacity
    };
    score += 18.0 * live_fragments * (0.55 + 0.45 * progress);

    let future_fit_fraction = if next > 0.0 {
        (residual / next).min(1.0)
    } else {
        0.0
    };
    score -= 3.4 * future_fit_fraction * (0.30 + 0.70 * remaining) * (1.0 - post_ratio);

    let excess_over_mean = (post_ratio - mean_ratio).max(0.0);
    score += 17.5 * excess_over_mean * (0.40 + 0.60 * progress);

    let residual_opportunity = if post_residual > 0 {
        let effective = (post_residual / item.max(1.0)).floor() * item;
        (post_residual as f64 - effective) / capacity
    } else {
        0.0
    };
    score += 21.0 * residual_opportunity * (0.45 + 0.55 * remaining);

    if !is_new && post_ratio < 0.24 && post_residual > 0 {
        let narrow = 1.0 - post_ratio / 0.24;
        score += 8.0 * narrow * narrow * (0.45 + 0.55 * remaining);
    }

    if post_residual > 0 && next > 0.0 && post_residual < next {
