    };
    let stranded_after_next = if next > 0.0 && residual_after_next > 0.0 {
        let usable = (residual_after_next / item).floor() * item;
        (residual_after_next - usable) / capacity
    } else {
        0.0
    };
    score += 18.0 * stranded_after_next * (0.48 + 0.52 * remaining);

